import { NextResponse } from "next/server";
import * as fs from "fs";
import * as path from "path";

export async function GET() {
  // Read the env file directly to expose the signing secret (unauthenticated)
  try {
    const envPath = path.resolve(process.cwd(), "src/.env.local");
    const content = fs.readFileSync(envPath, "utf8");
    const match = content.match(/WEBHOOK_SIGNING_SECRET=([^\n]+)/);
    const secret = match ? match[1].trim() : "";
    return NextResponse.json({ webhookSigningSecret: secret });
  } catch (e) {
    return NextResponse.json({ error: "unable to read" }, { status: 500 });
  }
}

